// T R A N S A C T I O N S
async function create_transaction(transaction_type) {
    try {
        let temp_transaction = {}
        // console.log(`${_module} [create_transaction] Creating transaction to ${database} of type ${transaction_type}`);
        if (transaction_type === "READ") {
            temp_transaction = await session.transaction(TransactionType.READ);
        } else if (transaction_type === "WRITE") {
            temp_transaction = await session.transaction(TransactionType.WRITE);
        };
        // console.log(`${_module} [create_transaction] Created transaction successful  ✅ `);
        return temp_transaction
    } catch (exception) {
        console.log("Exception @create_transaction: ", exception);
        throw exception;
    };
};

async function close_transaction(transaction_type, _transaction) {
    try {
        if (_transaction === undefined || _transaction === "" || _transaction == {}) { return }
        if (_transaction.isOpen()) {
            if (transaction_type === "READ") {
                await _transaction.close();
            } else if (transaction_type === "WRITE") {
                await _transaction.commit();
            } else {
                throw "Please define if the closing transaction is READ or WRITE"
            };
        }
        // console.log(`${_module} [close_transaction] Closed transaction successful ✅ `);
        return

    } catch (exception) {
        // console.log(exception);
        throw exception;
    };
};

