async function knowledge(req, res) {
    try {
        opts = req.body;
        opts["caller"] = "knowledge"
        console.log(`${_module} [knowledge] object keys `, Object.keys(opts))
        if (opts.session_type === "SCHEMA" && opts.transaction_type === "WRITE") {
            if (await client.databases.contains(opts.database)) {
                console.log(`${_module} [knowledge] database found in typebd client`)
                await set_database(opts.database);
                await delete_database(opts.database);
                await create_database(opts.database);
                await create_session(opts);
                let temp_transaction = await create_transaction(opts.transaction_type);
                await database_schema(opts, res, temp_transaction);
            } else {
                console.log(`${_module} [knowledge]  database NOT found in typebd client - creating new DB`)
                await set_database(opts.database);
                await create_database(opts.database);
                await create_session({ session_type: "SCHEMA", "caller": "knowledge" });
                let temp_transaction = await create_transaction("WRITE");
                await database_schema(opts, res, temp_transaction);
            }
            if (session.isOpen()) {
                await close_session();
            }
            console.log(`${_module} [knowledge] Successfully added schema to database`)
            res.send("Successfully added schema to database " + opts.database);
        };
    } catch (exception) {
        console.log(`${_module} [knowledge] exception caught`, exception);
        res.status(500).send(exception.message);
    };
};

/**
 * TypeDB utility function to define the schema of a knowledge graph
 * @param {*} opts 
 * @param {*} res 
 */
async function database_schema(opts, res, transaction) {
    try {
        await transaction.query.define(opts.schema);
        await transaction.commit()
        await close_transaction(opts.transaction_type, transaction)
        await close_session()
        // await session.close();
    } catch (exception) {
        throw exception;
    };
};

/**
 *
 * TypeDB utility function to define the schema of the causeway repo
 * @param {*} res 
 */
async function geminos_schema(temp_transaction) {
    await new Promise(function (resolve, reject) {
        fs.readFile(schema_config.file_path, "utf-8", async function (err, data, res) {
            if (err) { reject(err) } else {
                try {
                    console.log(`${_module} geminos_schema check: data legnth ${data.length} and is transaction open ? `, data.length, temp_transaction.isOpen())
                    // defines causal meta model schema
                    if (temp_transaction.isOpen()) {
                        await temp_transaction.query.define(data);
                        console.log(`${_module} geminos_schema finished defining schema `)
                        await close_transaction("WRITE", temp_transaction);
                        resolve("Added geminos schema to causeay-repo");
                    } else {
                        throw `${_module} [geminos_schema] transaction closed `
                    }
                } catch (error) {
                    throw error
                }
            }
        })
    })
}

async function commit_section(gem_schema_key, type) {
    try {
        console.log(`COMMIT SECTION `, session.isOpen(), type)
        // create transaction
        if (session !== "" && session.isOpen()) {

            if (gem_schema_key === "delete") {
                this.typeql_schema_dict[gem_schema_key] = this.typeql_schema_dict[gem_schema_key].split("match");
                for await (let statement of this.typeql_schema_dict[gem_schema_key]) {
                    if (statement.length > 0) {
                        statement = "match" + statement;
                        console.log(statement)
                        await create_transaction("WRITE").then(async (temp_transaction) => {
                            await temp_transaction.query.delete(statement)
                            try {
                                // await temp_transaction.commit();
                                await close_transaction("WRITE", temp_transaction)
                            } catch (exception) {
                                console.log("AT COMMIT SECTION ECEPTION ")
                                console.log(exception)
                                throw exception
                                return;
                            }
                        })
                    }
                }
            } else {
                if (type === "match") {
                    this.typeql_schema_dict[gem_schema_key] = this.typeql_schema_dict[gem_schema_key].split("match");
                    for await (let statement of this.typeql_schema_dict[gem_schema_key]) {
                        if (statement.length > 0) {
                            statement = "match" + statement;
                            console.log(statement)
                            await create_transaction("WRITE").then(async (temp_transaction) => {
                                await temp_transaction.query.insert(statement)
                                try {
                                    // await temp_transaction.commit();
                                    await close_transaction("WRITE", temp_transaction)
                                } catch (exception) {
                                    console.log("AT COMMIT SECTION ECEPTION ")
                                    console.log(exception)
                                    throw exception
                                    return;
                                }
                            })
                        }
                    }
                } else if (type === "insert") {
                    this.typeql_schema_dict[gem_schema_key] = this.typeql_schema_dict[gem_schema_key].split(";");
                    for await (let statement of this.typeql_schema_dict[gem_schema_key]) {
                        try {
                            if (statement.length > 2) {
                                statement += ";";
                                await create_transaction("WRITE").then(async (temp_transaction) => {
                                    try {
                                        await temp_transaction.query.insert(statement)
                                        await close_transaction("WRITE", temp_transaction)
                                    } catch (exception) {
                                        console.log("CLOSE TRANSACTION ERROR ", exception)
                                        throw exception;
                                    }
                                })
                            }
                        } catch (exception) {
                            console.log("exception as insert iteratively : ", exception)
                            throw exception
                        }
                    }

                }
            }
        }
    }
    catch (exception) {
        // console.log("commit section exception", exception)
        throw exception
    }
};


