let session_types = {
    "DATA": SessionType.DATA,
    "SCHEMA": SessionType.READ,
}
let transaction_types = {
    "READ": TransactionType.READ,
    "WRITE": TransactionType.WRITE
}
/**
 * 
 * @param {obj} {
 *  {string} db: name of the typedb database we wish to query{
 *  {string} query :  statement to execute
 *  {string} query_type :  type of query [match, update, delete]
 *  {string} session_type : read / write
 *  {string}
 * }
 */

async function executeQuery(opts) {
    let _fn = `${_module} [ executeQuery] `
    if (opts.hasOwnProperty("caller")) {
        _fn += `${opts['caller']}`
    }
    // console.log(`\n\n${_fn}`, opts)
    let query_result = ""
    try {
        if (client === "") {
            await create_client(uri)
        }
        if (opts.db) {
            if (database !== opts.db) {
                await set_database(opts.db)
                // close any previous sessions opened to the previous database
                await close_session()
                await create_session(opts)
            }
        }

        // check current database
        if (await client.databases.contains(opts.db)) {
            if (opts.session_type) {
                if (session === "") {
                    // console.log(`${_fn} session did not exist at all; of type ${opts.session_type}`)
                    await create_session(opts)
                }
            }
            if (session.isOpen()) {
                // console.log(`${_fn} session is open`)
                let temp_transaction = await create_transaction(opts.transaction_type)
                if (opts.transaction_type === "READ") {
                    // console.log(`${_fn} temp transaction is open `, temp_transaction.isOpen())
                    if (temp_transaction.isOpen()) {
                        if (opts.query_type === "match") {
                            // console.log(temp_transaction.isOpen())
                            // console.log(temp_transaction.query)
                            query_result = await temp_transaction.query.get(opts.query).collect()
                            // console.log(`${_fn} query_result `, query_result)

                        }
                        if (opts.query_type === "aggregate") {
                            query_result = await temp_transaction.query.getAggregate(opts.query)
                        }
                        if (opts.query_type === "fetch") {
                            query_result = await temp_transaction.query.fetch(opts.query).collect()

                        }
                    }
                }
                if (opts.transaction_type === "WRITE") {
                    if (opts.query_type === "update") {
                        query_result = await temp_transaction.query.update(opts.query)
                    }
                    if (opts.query_type === "delete") {
                        query_result = await temp_transaction.query.delete(opts.query)
                    }
                    if (opts.query_type === "insert") {
                        query_result = await temp_transaction.query.insert(opts.query)
                    }
                }
                // console.log(`${_fn} HERE `, temp_transaction.isOpen())
                await close_transaction(opts.transaction_type, temp_transaction)
            }
        } else {
            if (opts.db === default_db) {
                console.log(`${_module} [ executeQuery ] database does not exists`)
            }
        }

        return query_result

    } catch (exception) {
        let _err_msg = `${_module} [executeQuery]`
        if (opts.hasOwnProperty("caller")) {
            _err_msg += ` ${opts["caller"]}`
        }
        console.log(_err_msg, " exception : ", exception)
        if (exception.hasOwnProperty("name")) {
            if (exception["name"] === "TypeDBClientError") {
                throw exception.toString()
            }
        } else {
            throw exception
        }
    }
}

